쿼리 작성: select seller_state, seller_city, seller_count
from (
  select seller_state, seller_city, count(*) as seller_count,
         dense_rank() over (partition by seller_state order by count(*) desc, seller_city asc) as rnk
  from sellers
  group by seller_state, seller_city
) t
where rnk <= 3
order by seller_state asc, seller_count desc, seller_city asc;

